#!/usr/bin/env python3
"""Build offline product previews, editor HTML and media for a Superhive listing.
Uses only repository-owned original renders. Never publishes or edits a listing.
"""
import argparse,base64,html,json,mimetypes,re,zipfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#080c14;color:#edf3fc;font:16px/1.7 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:#a9eefa}button,input,textarea{font:inherit}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #74e9df;outline-offset:4px}.wrap{max-width:1160px;margin:auto;padding:26px}.top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #263142;padding:0 0 20px}.brand{font-weight:800;letter-spacing:.18em;color:white;text-decoration:none}.top span{font-size:.75rem;color:#a5b3c8}.hero{display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center;padding:76px 0 50px}.eyebrow{font-size:.72rem;font-weight:750;letter-spacing:.15em;color:#75e9d9;text-transform:uppercase}h1{font-size:clamp(2.8rem,5vw,4.5rem);line-height:1.06;letter-spacing:-.055em;margin:20px 0}h2{font-size:clamp(1.9rem,3vw,2.8rem);line-height:1.15;letter-spacing:-.035em}h3{line-height:1.3}p{color:#b5c2d7}.hero p{font-size:1.1rem}.hero figure{margin:0}.hero img{width:100%;border:1px solid #263142;border-radius:22px;background:#05080d}.pill{display:inline-block;border:1px solid #304055;border-radius:99px;padding:6px 13px;font-size:.76rem;color:#cad5e5;margin:3px}.cta{display:inline-block;background:#91f0d9;color:#071b1d;font-weight:750;padding:12px 20px;border-radius:9px;text-decoration:none;margin-top:15px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;padding:22px 0 64px;list-style:none;counter-reset:step}.steps li{background:#111927;border:1px solid #253145;border-radius:14px;padding:22px;color:#d1dceb;counter-increment:step}.steps li:before{content:"0" counter(step);display:block;font-size:.8rem;font-weight:800;color:#75e9d9;margin-bottom:12px}.feature{padding:52px 0;border-top:1px solid #253145}.copy{max-width:760px}.feature ul{padding-left:20px;color:#c2cee1}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:18px;margin-top:30px}figure{margin:0}figure img{display:block;width:100%;height:auto;border-radius:12px;background:#05080d;border:1px solid #253145}figcaption{font-size:.78rem;color:#8c9cb4;padding:12px 4px}.notice{padding:20px 24px;background:#101e26;border-left:3px solid #75e9d9;color:#c5d6e0;border-radius:0 9px 9px 0}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;margin:24px 0;font-size:.93rem}th,td{text-align:left;padding:14px;border-bottom:1px solid #263142}th{color:#7cebdc}td{color:#c5d1e1}th:first-child{width:60%}.requirements{padding-left:20px;color:#bdcadc}.faq details{padding:17px 0;border-bottom:1px solid #253145}.faq summary{cursor:pointer;font-weight:650}.faq p{max-width:850px}footer{border-top:1px solid #263142;margin-top:50px;padding:25px 0;color:#8e9fb8;font-size:.78rem}.upload-grid{display:grid;gap:14px}.upload-row{display:grid;grid-template-columns:minmax(180px,1fr) 2fr;gap:18px;align-items:center}input,textarea{width:100%;background:#111927;color:#edf3fc;border:1px solid #35465e;border-radius:8px;padding:10px}textarea{min-height:220px;font-family:monospace;font-size:.8rem}button{cursor:pointer;border:1px solid #3d556c;border-radius:8px;padding:9px 16px;background:#19283a;color:#eaf3ff;margin:5px 8px 5px 0}button[aria-pressed=true]{background:#91f0d9;color:#071b1d}#status{min-height:2em;color:#91f0d9}.hidden{display:none}@media(max-width:720px){.wrap{padding:20px}.hero{grid-template-columns:1fr;gap:28px;padding:40px 0}.hero figure{max-width:520px}.steps{grid-template-columns:1fr;gap:10px;padding-bottom:35px}.feature{padding:35px 0}.top span{max-width:150px;text-align:right}.upload-row{grid-template-columns:1fr;gap:5px}h1{font-size:3rem}th,td{padding:10px;font-size:.85rem}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{body{background:white;color:black}.wrap{max-width:none}p,td,li,figcaption{color:#333!important}.hero{padding:10px 0}.feature{break-inside:avoid}.cta,.top{display:none}}'''
def e(x):return html.escape(str(x),quote=True)
def li(items):return '<ul>'+''.join('<li>'+e(x)+'</li>' for x in items)+'</ul>'
def build(edition,out,urlmap):
 source=ROOT/'docs/storefront';data=json.loads((source/f'{edition}.json').read_text());registry=json.loads((ROOT/'docs/manual/media.json').read_text())
 keys=list(dict.fromkeys([data['hero']]+[k for b in data['blocks'] for k in b['media']]))
 media={};entries=[]
 for key in keys:
  item=registry[key];path=(ROOT/'docs/manual'/item['path']).resolve()
  if edition=='free' and '/assets/free/' not in path.as_posix():raise ValueError('Free listing may only package Free images')
  name=key+path.suffix;target=out/'media'/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(path.read_bytes())
  media[key]='media/'+name;entries.append({'file':'media/'+name,'alt':item['alt']})
 def visual(key,hero=False):
  item=registry[key];caption=('Original Blender render. Example scene assets are not included.' if hero else
           'Eight light layers shown separately. Spectral Swarm is shown above. Example scene geometry is not included.' if key=='environment-layers' else item['caption'])
  return '<figure><img src="'+e(media[key])+'" alt="'+e(item['alt'])+'" width="100%" style="height:auto" loading="'+('eager' if hero else 'lazy')+'"><figcaption>'+e(caption)+'</figcaption></figure>'
 parts=['<article class="product"><header class="hero"><div><span class="eyebrow">'+e(data['badge'])+'</span><h1>'+e(data['headline'])+'</h1><p>'+e(data['intro'])+'</p><p>'+''.join('<span class="pill">'+e(x)+'</span> ' for x in data['benefits'])+'</p><a class="cta" href="#'+edition+'-features">Explore '+e(data['name'])+'</a></div>'+visual(data['hero'],True)+'</header>', '<section id="'+edition+'-features"><h2>From track to reaction.</h2><ol class="steps">'+''.join('<li>'+e(x)+'</li>' for x in data['steps'])+'</ol></section>']
 for b in data['blocks']:
  parts.append('<section class="feature" id="'+edition+'-'+e(b['id'])+'"><div class="copy"><span class="eyebrow">'+e(b['tag'])+'</span><h2>'+e(b['title'])+'</h2><p>'+e(b['text'])+'</p>'+li(b['items'])+'</div><div class="gallery">'+''.join(visual(k) for k in b['media'])+'</div></section>')
 rows=[('Music reactions on geometry and native lights','Included','Included'),('Five object looks and custom object looks','Included','Included'),('Ripple, Through Objects, Level Meter and optional glow','Included','Included'),('Generated environment lights, beams, lasers and signals','—','Included'),('Spectral Swarm: Vortex, Supernova and Orbit','—','Included'),('Cage placement, environment presets and Live Mix','—','Included')]
 parts+=['<section class="feature"><span class="eyebrow">CHOOSE YOUR EDITION</span><h2>Start free. Build environments with Pro.</h2><div class="table-wrap"><table><thead><tr><th scope="col">Feature</th><th scope="col">Free</th><th scope="col">Pro</th></tr></thead><tbody>'+''.join('<tr><th scope="row">'+e(a)+'</th><td>'+e(b)+'</td><td>'+e(c)+'</td></tr>' for a,b,c in rows)+'</tbody></table></div><p>Pro includes Free. Install one edition at a time.</p></section>', '<section class="feature"><h2>Before you install.</h2>'+li(data['requirements'])+'<p class="notice">Demonstrations use original example scenes. The product supplies the add-on and guides; you bring your scene and music.</p></section>', '<section class="feature faq"><h2>A few useful answers.</h2>'+''.join('<details><summary>'+e(q)+'</summary><p>'+e(a)+'</p></details>' for q,a in data['faq'])+'</section></article>']
 fragment='\n'.join(parts)
 # Editor fragment remains semantic HTML, without scripts, CSS blocks or data URLs.
 editor=re.sub(r' class="[^"]*"','',fragment)
 editor=editor.replace('<details>','<div>').replace('</details>','</div>').replace('<summary>','<h3>').replace('</summary>','</h3>')
 for entry in entries:
  if entry['file'] in urlmap:
   url=urlmap[entry['file']]
   if not isinstance(url,str) or not url.startswith('https://'):raise ValueError('Image URLs must use HTTPS')
   editor=editor.replace('src="'+entry['file']+'"','src="'+e(url)+'"')
 (out/f'noctune-{edition}-description.html').write_text(editor+'\n')
 embedded=fragment
 for entry in entries:
  path=out/entry['file'];mime=mimetypes.guess_type(path.name)[0];url='data:'+mime+';base64,'+base64.b64encode(path.read_bytes()).decode()
  embedded=embedded.replace('src="'+entry['file']+'"','src="'+url+'"')
 page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="'+e(data['summary'])+'"><title>'+e(data['title'])+'</title><style>'+CSS+'</style></head><body><main class="wrap"><nav class="top" aria-label="Brand"><a class="brand" href="#">NOCTUNE</a><span>'+e(data['name'])+' · '+e(data['version'])+'</span></nav>'+embedded+'<footer>Original Noctune product preview · '+e(data['name'])+' '+e(data['version'])+' · GPL-3.0-or-later</footer></main></body></html>'
 (out/f'noctune-{edition}-preview.html').write_text(page)
 metadata={k:data[k] for k in ['name','version','title','summary']};metadata['tags']=['Blender','music visualizer','audio reactive','animation','lighting']+(['VFX','lasers','lightning','particles'] if edition=='pro' else ['materials'])
 (out/f'noctune-{edition}-listing.json').write_text(json.dumps(metadata,indent=2,ensure_ascii=False)+'\n')
 return {'name':data['name'],'edition':edition,'html':editor,'media':entries}

PUBLISH_JS='''const data=JSON.parse(document.getElementById('listing-data').textContent);let current=data[0];const fields=document.getElementById('fields'),output=document.getElementById('output'),status=document.getElementById('status');let maps={};function refresh(){let doc=new DOMParser().parseFromString(current.html,'text/html');let count=0;doc.querySelectorAll('img').forEach(img=>{let path=img.getAttribute('src'),url=(maps[path]||'').trim();if(url.startsWith('https://')){img.setAttribute('src',url);count++}});output.value=doc.body.innerHTML;status.textContent=count+' of '+doc.querySelectorAll('img').length+' image placements use hosted URLs. Upload and link every image before pasting.'}function select(i){current=data[i];document.querySelectorAll('[data-edition]').forEach((b,n)=>b.setAttribute('aria-pressed',n===i));fields.replaceChildren();current.media.forEach(m=>{let row=document.createElement('div');row.className='upload-row';let label=document.createElement('label');label.textContent=m.file;let input=document.createElement('input');input.type='url';input.placeholder='https://… hosted image URL';input.value=maps[m.file]||'';input.id='url-'+fields.children.length;label.htmlFor=input.id;input.addEventListener('input',()=>{maps[m.file]=input.value;refresh()});row.append(label,input);fields.append(row)});refresh()}document.querySelectorAll('[data-edition]').forEach((b,i)=>b.addEventListener('click',()=>select(i)));document.getElementById('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(output.value);status.textContent='HTML copied. Confirm every image URL before publishing.'}catch{output.focus();output.select();status.textContent='Select and copy the HTML below with Ctrl+C or Command+C.'}});document.getElementById('download').addEventListener('click',()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([output.value],{type:'text/html;charset=utf-8'}));a.download='noctune-'+current.edition+'-description.html';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});select(0);'''
def main():
 parser=argparse.ArgumentParser();parser.add_argument('--edition',choices=['free','pro','all'],default='all');parser.add_argument('--image-urls',type=Path);args=parser.parse_args()
 source=ROOT/'docs/storefront';editions=[x for x in ['free','pro'] if (source/f'{x}.json').exists()] if args.edition=='all' else [args.edition]
 if any(not(source/f'{x}.json').exists() for x in editions):raise ValueError('Edition source not available')
 out=source/'build';out.mkdir(parents=True,exist_ok=True)
 urls=json.loads(args.image_urls.read_text()) if args.image_urls else {}
 listings=[build(ed,out,urls) for ed in editions]
 # Safe embedded JSON: no content can close the script element.
 payload=json.dumps(listings,ensure_ascii=False).replace('<','\\u003c').replace('&','\\u0026')
 buttons=''.join('<button type="button" data-edition="'+e(d['edition'])+'" aria-pressed="false">'+e(d['name'])+'</button>' for d in listings)
 links=''.join('<p><a href="noctune-'+e(d['edition'])+'-preview.html">Open '+e(d['name'])+' standalone preview</a> · <a href="noctune-'+e(d['edition'])+'-description.html">Open editor HTML</a></p>' for d in listings)
 index='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Noctune · Superhive listing kit</title><style>'+CSS+'</style></head><body><main class="wrap"><nav class="top"><span class="brand">NOCTUNE</span><span>Superhive listing kit</span></nav><h1>Ready for your product page.</h1><p>Open a standalone preview to review the design. Use the editor HTML for your product description. Superhive controls the final styling; the preview is an original presentation, not a replica of its editor.</p>'+links+'<h2>Prepare the editor HTML.</h2><ol><li>Upload the files in <strong>media</strong> to your product’s media editor.</li><li>Paste each hosted HTTPS image URL below. Local image paths work in this extracted kit; they will not work on the live marketplace.</li><li>Copy or download the generated HTML, paste it into the product editor’s HTML/source mode if available, and check Superhive’s preview. If that mode is unavailable, use the rendered description and insert the uploaded images in the visual editor.</li></ol><p>Price, product links, licensing choices and support contact are configured separately in your seller dashboard. Nothing in this kit publishes a listing.</p>'+buttons+'<div id="fields" class="upload-grid"></div><p id="status" role="status" aria-live="polite"></p><button id="copy" type="button">Copy description HTML</button><button id="download" type="button">Download description HTML</button><label for="output"><h2>Description source</h2></label><textarea id="output" readonly spellcheck="false"></textarea><footer>Uses only original Noctune renders. No stock scenes, customer reviews or performance guarantees.</footer><script type="application/json" id="listing-data">'+payload+'</script><script>'+PUBLISH_JS+'</script></main></body></html>'
 (out/'index.html').write_text(index)
 (out/'image-urls.example.json').write_text(json.dumps({m['file']:'' for d in listings for m in d['media']},indent=2)+'\n')
 readme='''NOCTUNE — SUPERHIVE LISTING KIT\n\n1. Extract this ZIP and open index.html.\n2. Open the *-preview.html files to review the standalone product pages. Their images are embedded and work offline.\n3. Upload the media folder images to Superhive and paste their hosted HTTPS URLs into index.html. Copy/download the resulting description HTML.\n4. Paste it into the product description editor’s HTML/source mode if offered. Marketplace sanitization can change styling; confirm its own preview before publishing. The descriptions also work as copy for a visual editor.\n5. Set pricing, listing links, license information and support details in the seller dashboard. No prices or reviews were invented.\n\n*-description.html = semantic product-description fragments, no scripts or stylesheet blocks. Relative image paths work locally; replace them with hosted URLs before use on the marketplace.\n*-listing.json = suggested title, short summary, tags and source add-on version.\nmedia/ = original Blender renders to upload; example scene assets/music are not included.\n\nThe preview pages are original presentations and do not represent a live or published Superhive listing. The marketplace editor’s exact supported markup has not been verified.\n\nTo rebuild from source: python tools/build_storefront.py --edition all\nFor noninteractive hosted URLs: --image-urls path/to/image-urls.json (keys as in image-urls.example.json).\n'''
 (out/'READ-ME.txt').write_text(readme)
 (out/'LICENSE.txt').write_bytes((ROOT/'LICENSE').read_bytes())
 dest=ROOT/'dist'/('noctune-superhive-listing-kit.zip' if len(editions)>1 else f'noctune-{editions[0]}-superhive-listing-kit.zip');dest.parent.mkdir(exist_ok=True)
 allowed_media={m['file'] for d in listings for m in d['media']}
 files={p.relative_to(out).as_posix():p.read_bytes() for p in out.rglob('*') if p.is_file() and (p.name in ['index.html','READ-ME.txt','LICENSE.txt','image-urls.example.json'] or p.relative_to(out).as_posix() in allowed_media or any(p.name.startswith('noctune-'+ed+'-') for ed in editions))}
 with zipfile.ZipFile(dest,'w',zipfile.ZIP_DEFLATED) as z:
  for name,content in sorted(files.items()):
   info=zipfile.ZipInfo(name,(2026,1,1,0,0,0));info.compress_type=zipfile.ZIP_DEFLATED;info.external_attr=0o644<<16;z.writestr(info,content)
 print('Built',dest,'with',len(files),'files')
if __name__=='__main__':main()
